package dev.pocketengine.runtime.routes;

import dev.pocketengine.core.*;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

public final class PhoneRouteSessionTest {
    private static final String TASK="task",RUN="run";
    static final class Repo implements PhoneRouteSession.Repository {JSONObject value;long version=1;boolean withdrawn;public JSONArray routes(String g,RunControl c){return new JSONArray();}public JSONObject route(String id,String digest,String goal,RunControl c)throws Exception{if(withdrawn)throw new SecurityException("withdrawn");return new JSONObject(value.toString());}public void withdraw(String id,String d,RunControl c){withdrawn=true;}public long packageVersion(String p){return version;}public String hostUserIdentity(){return "fixture-original-user";}public void requireCurrentSources(RunControl c)throws Exception{c.check();}}
    static final class Phone implements PhonePort {JSONObject current;int observations,executions;public boolean isConnected(){return true;}public JSONObject observe(boolean image,RunControl c)throws Exception{observations++;return new JSONObject(current.toString());}public JSONObject execute(String t,JSONObject a,RunControl c){executions++;throw new AssertionError("A route resolver must not dispatch actions");}public void clearReferences(){}}
    private static RunControl control(){RunControl c=new RunControl();c.bindHostRun(TASK,RUN,1);return c;}
    private static JSONObject scene()throws Exception{return new JSONObject().put("ok",true).put("treeSchemaVersion",1).put("observationSources",new JSONObject().put("treeAvailable",true)).put("windows",new JSONArray().put(new JSONObject().put("rootAvailable",true))).put("observationId","fresh").put("packageName","app.example").put("observationBinding",new JSONObject().put("taskId",TASK).put("runId",RUN).put("epoch",1).put("displayId",2).put("sessionId","session")).put("nodes",new JSONArray().put(new JSONObject().put("id","n").put("resourceId","app.example:id/search").put("role","Button").put("text","搜索").put("visible",true).put("enabled",true).put("clickable",true)).put(new JSONObject().put("id","header").put("resourceId","app.example:id/header").put("role","Text").put("text","主页").put("visible",true).put("enabled",true)));}
    private static JSONObject learned(Repo repo,Phone phone,RunControl c)throws Exception {PhoneRouteSession recording=new PhoneRouteSession(TASK,"打开搜索",phone,c,repo,false);recording.after("phone_click_node",new JSONObject().put("nodeId","n"),new JSONObject().put("ok",true).put("accepted",true),phone.current,"op",c);JSONObject candidate=recording.candidate(c);assertNotNull(candidate);assertFalse(candidate.getBoolean("businessVerified"));repo.value=candidate;return candidate;}
    @Test public void routeResolvesFreshUniqueTargetWithoutDispatchingOrRestoringOldIds()throws Exception {RunControl c=control();Repo repo=new Repo();Phone phone=new Phone();phone.current=scene();JSONObject candidate=learned(repo,phone,c);PhoneRouteSession replay=new PhoneRouteSession(TASK,"打开搜索",phone,c,repo,false);replay.execute(PhoneRouteSession.REPLAY,new JSONObject().put("routeId",candidate.getString("routeId")).put("digest",candidate.getString("digest")),phone.current,"call",c);NativeToolPlan plan=replay.take("call",c);plan.consume(PhoneRouteSession.REPLAY,"call",c);NativeToolPlan.Step step=plan.next(c);assertEquals("fresh",step.arguments().getString("observationId"));assertEquals("n",step.arguments().getString("nodeId"));assertEquals(1,phone.observations);assertEquals(0,phone.executions);assertNull(plan.next(c));plan.close();}
    @Test public void versionWithdrawalAndAmbiguousTargetStopBeforeAnyAction()throws Exception {for(String kind:new String[]{"version","withdrawn","ambiguous","page","foreign_epoch"}){RunControl c=control();Repo repo=new Repo();Phone phone=new Phone();phone.current=scene();JSONObject candidate=learned(repo,phone,c);PhoneRouteSession replay=new PhoneRouteSession(TASK,"打开搜索",phone,c,repo,false);replay.execute(PhoneRouteSession.REPLAY,new JSONObject().put("routeId",candidate.getString("routeId")).put("digest",candidate.getString("digest")),phone.current,"call",c);NativeToolPlan plan=replay.take("call",c);plan.consume(PhoneRouteSession.REPLAY,"call",c);if(kind.equals("version"))repo.version=2;else if(kind.equals("withdrawn"))repo.withdrawn=true;else if(kind.equals("page"))phone.current.getJSONArray("nodes").getJSONObject(1).put("text","不同页面");else if(kind.equals("foreign_epoch"))phone.current.getJSONObject("observationBinding").put("epoch",2);else phone.current.getJSONArray("nodes").put(new JSONObject(phone.current.getJSONArray("nodes").getJSONObject(0).toString()).put("id","second"));assertThrows(kind,SecurityException.class,()->plan.next(c));assertEquals(0,phone.executions);}}
    @Test public void restoredTaskAndCommitmentControlsNeverCreateReusableRoutes()throws Exception {RunControl c=control();Repo repo=new Repo();Phone phone=new Phone();phone.current=scene();PhoneRouteSession restored=new PhoneRouteSession(TASK,"打开搜索",phone,c,repo,true);assertFalse(restored.replayAllowed());PhoneRouteSession fresh=new PhoneRouteSession(TASK,"确认支付",phone,c,repo,false);phone.current.getJSONArray("nodes").getJSONObject(0).put("text","确认支付");fresh.after("phone_click_node",new JSONObject().put("nodeId","n"),new JSONObject().put("ok",true),phone.current,"op",c);assertNull(fresh.candidate(c));}
    @Test public void originalForwardBackwardScrollDirectionsResolveWithoutIntroducingCoordinateOrGestureAliases()throws Exception {
        for(String direction:new String[]{"forward","backward"}){RunControl c=control();Repo repo=new Repo();Phone phone=new Phone();phone.current=scene();PhoneRouteSession recording=new PhoneRouteSession(TASK,"打开搜索",phone,c,repo,false);recording.after("phone_scroll_node",new JSONObject().put("nodeId","n").put("direction",direction),new JSONObject().put("ok",true).put("accepted",true),phone.current,"scroll-op",c);JSONObject candidate=recording.candidate(c);repo.value=candidate;
            PhoneRouteSession replay=new PhoneRouteSession(TASK,"打开搜索",phone,c,repo,false);replay.execute(PhoneRouteSession.REPLAY,new JSONObject().put("routeId",candidate.getString("routeId")).put("digest",candidate.getString("digest")),phone.current,"scroll-call",c);NativeToolPlan plan=replay.take("scroll-call",c);plan.consume(PhoneRouteSession.REPLAY,"scroll-call",c);NativeToolPlan.Step step=plan.next(c);assertEquals(NativeToolPlan.Tool.SCROLL_NODE,step.tool);assertEquals(direction,step.arguments().getString("direction"));assertEquals(0,phone.executions);plan.close();
        }
    }
    @Test public void modifiedDigestOrUnsupportedCachedActionNeverBecomesANativeStep()throws Exception {
        for(String kind:new String[]{"digest","tool","goal","label","user"}){RunControl c=control();Repo repo=new Repo();Phone phone=new Phone();phone.current=scene();JSONObject candidate=learned(repo,phone,c);
            if(kind.equals("digest"))candidate.put("packageVersion",2);else if(kind.equals("tool"))candidate.getJSONArray("steps").getJSONObject(0).put("tool","phone_type");else if(kind.equals("goal"))candidate.put("goal","其他目标");else if(kind.equals("label"))candidate.getJSONArray("steps").getJSONObject(0).getJSONObject("selector").put("textExact","确认支付");else candidate.put("hostUserIdentity","other-user");
            if(!kind.equals("digest"))candidate.put("digest",PhoneRouteSession.digest(candidate));repo.value=candidate;PhoneRouteSession replay=new PhoneRouteSession(TASK,"打开搜索",phone,c,repo,false);
            assertThrows(kind,SecurityException.class,()->replay.execute(PhoneRouteSession.REPLAY,new JSONObject().put("routeId",candidate.getString("routeId")).put("digest",candidate.getString("digest")),phone.current,"call",c));assertNull(replay.take("call",c));assertEquals(0,phone.executions);
        }
    }
    @Test public void afterPageDivergenceKeepsReceiptAndCannotRestartTheRoute()throws Exception {RunControl c=control();Repo repo=new Repo();Phone phone=new Phone();phone.current=scene();JSONObject candidate=learned(repo,phone,c),args=new JSONObject().put("routeId",candidate.getString("routeId")).put("digest",candidate.getString("digest"));PhoneRouteSession replay=new PhoneRouteSession(TASK,"打开搜索",phone,c,repo,false);replay.execute(PhoneRouteSession.REPLAY,args,phone.current,"call",c);NativeToolPlan plan=replay.take("call",c);plan.consume(PhoneRouteSession.REPLAY,"call",c);plan.next(c);phone.current.getJSONArray("nodes").getJSONObject(1).put("text","操作后不同页面");assertFalse(replay.replayPostcondition("phone_click_node",new JSONObject().put("ok",true),phone.current));JSONObject again=replay.execute(PhoneRouteSession.REPLAY,args,phone.current,"second-call",c);assertFalse(again.getBoolean("accepted"));assertEquals("route_already_attempted",again.getString("code"));assertNull(replay.take("second-call",c));assertEquals(0,phone.executions);plan.close();}
}
